/**
 * Files an ordinary issue for each recurring-issue rule whose latest occurrence has started.
 *
 * Must call (do not reimplement): createIssue, can
 */
import { can } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const DAY_MS = 86_400_000;

function toDayNumber(date: string): number {
  const [y, m, d] = date.split("-").map(Number);
  const value = new Date(0);
  value.setUTCFullYear(y!, m! - 1, d!);
  value.setUTCHours(0, 0, 0, 0);
  return Math.round(value.getTime() / DAY_MS);
}

function fromDayNumber(day: number): string {
  const date = new Date(day * DAY_MS);
  const year = String(date.getUTCFullYear()).padStart(4, "0");
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const dom = String(date.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${dom}`;
}

/** The calendar date at `now` in `timeZone`. */
function localDate(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    calendar: "iso8601",
    numberingSystem: "latn",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const pick = (type: string) =>
    parts.find((part) => part.type === type)?.value ?? "";
  return `${pick("year").padStart(4, "0")}-${pick("month")}-${pick("day")}`;
}

/** Latest occurrence day that has started by `now`, or null. */
export function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = toDayNumber(localDate(now, rule.timezone));
  const start = toDayNumber(rule.startsOn);
  if (today < start) return null;

  let day = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    // Day 0 (1970-01-01) was a Thursday, ISO weekday 4.
    const isoWeekday = (((today + 3) % 7) + 7) % 7 + 1;
    day = today - ((isoWeekday - rule.weekday + 7) % 7);
    if (day < start) return null;
  }
  return fromDayNumber(day);
}

async function processRule(rule: RecurringIssue, now: Date): Promise<boolean> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || project.archivedAt !== null) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.setPaused(rule.orgId, rule.id, true);
    return false;
  }

  let assigneeId = rule.assigneeId;
  if (assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
    if (assignee === null || assignee.status !== "active") assigneeId = null;
  }

  await createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringRepo.setLastOccurrence(rule.orgId, rule.id, occurrence);
  return true;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listAllActiveRules();

    for (const rule of rules) {
      try {
        if (await processRule(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          ruleId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
