/**
 * Recurring-issue rules. Reads are org-scoped except `listAllActiveRules`,
 * which the background job uses to sweep every tenant.
 */
import { and, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurringIssue } from "@/types/recurring-issue";

function toRule(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    title: row.title,
    priority: row.priority as IssuePriority,
    assigneeId: row.assigneeId === null ? null : brandId<UserId>(row.assigneeId),
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: row.createdAt as IsoTimestamp,
    updatedAt: row.updatedAt as IsoTimestamp,
  };
}

export async function countRules(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function insertRule(
  rule: Omit<
    CreateRecurringIssueInput,
    "priority" | "assigneeId" | "weekday"
  > & {
    priority: IssuePriority;
    assigneeId: UserId | null;
    weekday: number | null;
  },
  createdBy: UserId,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: rule.title,
      priority: rule.priority,
      assigneeId: rule.assigneeId,
      cadence: rule.cadence,
      weekday: rule.weekday,
      timezone: rule.timezone,
      startsOn: rule.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRule(row);
}

export async function findRule(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .get();
  return row ? toRule(row) : null;
}

export async function listRules(orgId: OrgId): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(recurringIssues.createdAt, sql`rowid`)
    .all()
    .map(toRule);
}

/** Cross-tenant on purpose: the job sweeps every organization's live rules. */
export async function listAllActiveRules(): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(recurringIssues.createdAt, sql`rowid`)
    .all()
    .map(toRule);
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .returning()
    .get();
  if (!row) throw new Error(`Recurring issue ${id} not found in org ${orgId}`);
  return toRule(row);
}

export async function setLastOccurrence(
  orgId: OrgId,
  id: string,
  occurrenceOn: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .run();
}
